 * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
 * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
 */
public Integer getMembershipLevel() {
    int points = getMembershipPoints();
    if (points <= 1) {
        return 1;
    }
    if (points <= 3) {
        return 2;
    }
    if (points <= 5) {
        return 3;
    }
    return 4;
}

